process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const A=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/a.html', A);
  const br=await chromium.launch();
  const p=await (await br.newContext({viewport:{width:1400,height:1400}})).newPage();
  const kl=[]; p.on('pageerror',e=>kl.push(String(e).slice(0,130)));
  await p.goto('file:///tmp/a.html',{waitUntil:'networkidle'});
  await p.waitForTimeout(500);
  await p.fill('#pav','Animonda GranCarno konservai šunims, 400 g');
  await p.selectOption('#kat','maistas');
  await p.waitForTimeout(300);
  await p.evaluate(()=>{ rodyti(3); });
  await p.waitForTimeout(500);
  out.gpais_pries=await p.locator('#gpais-sk').isVisible();
  await p.check('#g-imp');
  await p.waitForTimeout(500);
  out.gpais_po=await p.locator('#gpais-sk').isVisible();
  out.eiluciu_pradzioje=await p.locator('#pak-lent tr').count();
  await p.click('text=Pavyzdys: konservai 6-pack');
  await p.waitForTimeout(600);
  out.eiluciu_po_pvz=await p.locator('#pak-lent tr').count();
  await p.fill('#g-kiekis','60');
  await p.waitForTimeout(600);
  out.suma=await p.locator('#pak-suma').innerText();
  out.patikra_gpais=await p.locator('#patikra').innerText();
  await p.screenshot({path:'/tmp/gp.png',fullPage:true});
  out.js_klaidos=kl;
  await br.close();
  try{ await put('screenshots/gp.png', fs.readFileSync('/tmp/gp.png'), 'gpais'); }catch(e){}
  await put('analize/gpais.json', Buffer.from(JSON.stringify(out,null,2)),'g');
}
main().catch(async e=>{ await put('analize/gpais.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
